// Client-side search over page titles, descriptions and headings.
// The index (window.KM_SEARCH_INDEX) is a same-origin script generated by site/gen.
(function () {
  "use strict";
  var input = document.getElementById("search-input");
  var list = document.getElementById("search-results");
  var index = window.KM_SEARCH_INDEX || [];
  if (!input || !list) return;
  var root = document.body.getAttribute("data-root") || "";

  function norm(s) { return (s || "").toLowerCase(); }

  function search(q) {
    var terms = norm(q).split(/\s+/).filter(Boolean);
    if (!terms.length) return [];
    var results = [];
    index.forEach(function (e) {
      var title = norm(e.t), desc = norm(e.d);
      var heads = e.h || [];
      var hay = title + " " + desc + " " + heads.map(function (h) { return norm(h[0]); }).join(" ");
      if (!terms.every(function (t) { return hay.indexOf(t) >= 0; })) return;
      var score = 0, anchor = "", label = "";
      terms.forEach(function (t) {
        if (title.indexOf(t) >= 0) score += 10;
        if (title.indexOf(t) === 0) score += 5;
        if (desc.indexOf(t) >= 0) score += 2;
      });
      if (title === norm(q).trim()) score += 50;
      if (score < 10 * terms.length) {
        for (var i = 0; i < heads.length; i++) {
          var h = norm(heads[i][0]);
          if (terms.every(function (t) { return h.indexOf(t) >= 0; })) {
            anchor = "#" + heads[i][1];
            label = heads[i][0];
            score += 4;
            break;
          }
        }
      }
      results.push({ e: e, score: score, anchor: anchor, label: label });
    });
    results.sort(function (a, b) { return b.score - a.score || a.e.t.localeCompare(b.e.t); });
    return results.slice(0, 12);
  }

  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text) n.textContent = text;
    return n;
  }

  var selected = -1;
  function render() {
    var q = input.value;
    list.textContent = "";
    selected = -1;
    if (!q.trim()) { list.hidden = true; return; }
    var rs = search(q);
    if (!rs.length) {
      list.appendChild(el("li", "r-empty", "No results"));
    }
    rs.forEach(function (r) {
      var li = el("li");
      var a = el("a");
      a.href = root + r.e.u + r.anchor;
      a.appendChild(el("span", "r-sec", r.e.s));
      a.appendChild(el("span", "r-title", r.label ? r.e.t + " › " + r.label : r.e.t));
      if (r.e.d) a.appendChild(el("span", "r-desc", r.e.d));
      li.appendChild(a);
      list.appendChild(li);
    });
    list.hidden = false;
  }

  function move(d) {
    var links = list.querySelectorAll("a");
    if (!links.length) return;
    if (selected >= 0) links[selected].classList.remove("sel");
    selected = (selected + d + links.length) % links.length;
    links[selected].classList.add("sel");
    links[selected].scrollIntoView({ block: "nearest" });
  }

  input.addEventListener("input", render);
  input.addEventListener("keydown", function (ev) {
    if (ev.key === "ArrowDown") { ev.preventDefault(); move(1); }
    else if (ev.key === "ArrowUp") { ev.preventDefault(); move(-1); }
    else if (ev.key === "Enter") {
      var links = list.querySelectorAll("a");
      var target = links[selected >= 0 ? selected : 0];
      if (target) { ev.preventDefault(); window.location.href = target.href; }
    } else if (ev.key === "Escape") { input.value = ""; render(); input.blur(); }
  });
  document.addEventListener("click", function (ev) {
    if (!list.contains(ev.target) && ev.target !== input) list.hidden = true;
  });
  input.addEventListener("focus", function () { if (input.value.trim()) render(); });
  document.addEventListener("keydown", function (ev) {
    if (ev.key === "/" && document.activeElement !== input && !/input|textarea/i.test(document.activeElement.tagName)) {
      ev.preventDefault();
      input.focus();
    }
  });
})();
